func TestPyLogCorpus(t *testing.T) {
	for _, c := range pyLogCases {
		if got := pyLog(c.x); got != c.want {
			t.Errorf("pyLog(%.17g) = %.17g, want %.17g", c.x, got, c.want)
		}
	}
}
